/// The advisory when `callisto version` has work for the selection: a release plans only versions already written.
pub(crate) fn pending_version_diagnostic(
    packages: &[callisto_model::ReleasePackageId],
) -> Option<callisto_model::Diagnostic> {
    if packages.is_empty() {
        return None;
    }
    let names = packages
        .iter()
        .map(|package| format!("`{package}`"))
        .collect::<Vec<_>>();
    Some(callisto_model::Diagnostic {
        code: callisto_model::DiagnosticCode::PendingVersionWork,
        severity: callisto_model::DiagnosticSeverity::Info,
        message: format!(
            "pending version work for {} is not in this plan: run `callisto version` (or merge the release PR) first",
            names.join(", ")
        ),
        package: None,
        path: None,
        escalated_by: None,
        governed_by: None,
    })
}

/// Stderr warning for a tag that exists here but not on `origin`.
fn tag_missing_from_origin_note(tag: &str) -> String {
    format!(
        "warning: tag `{tag}` exists here but not on `origin`, so its release may not have finished: check out the \
         tagged commit and run `callisto release` again, or push the tag if the release is complete"
    )
}

/// Exact stdout when no package has an unreleased version.
pub const NOTHING_TO_RELEASE: &str = "Nothing to release.";

fn release(packages: &[String], receipt: Option<&std::path::Path>, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let selections = parse_selections(packages)?;
    let runner = CliCommandRunner;
    let workspace = load_workspace(global, &runner)?;
    let root = workspace.root.clone();
    let locator = IgnoreWalkLocator::new(&root);
    if let Some(route) = ci_release_route(&workspace)?.filter(|_| !global.dry_run) {
        return Err(CliError::ReleaseRequiresCiRoute {
            reason: route.to_string(),
        });
    }
    let mode = if global.dry_run {
        LocalReleaseSource::Preview
    } else {
        LocalReleaseSource::Trusted
    };
    // The one `ls-remote` is network latency; it runs beside the plan rather than before it. Best effort: a tag that
    // never reached `origin` is a release that did not finish, whatever the plan says next.
    let probe = origin_tag_probe(&workspace).ok().flatten();
    let (missing, planned) = std::thread::scope(|scope| {
        let missing = probe.as_ref().map(|probe| scope.spawn(|| probe.missing(&runner)));
        let planned = plan_loaded_release(&workspace, &selections, mode);
        (missing.map(|handle| handle.join().unwrap_or_default()), planned)
    });
    for tag in missing.unwrap_or_default() {
        eprintln!("{}", tag_missing_from_origin_note(&tag));
    }
    let plan = match planned {
        Err(error)
            if matches!(
                &error,
                GraphError::ReleaseSelectionInvalid {
                    reason: callisto_graph::error::ReleaseSelectionInvalidReason::NotARelease,
                    ..
                }
            ) =>
        {
            // The version work that would make the selection a release is the answer to the refusal.
            let pending = PendingWork::of(pending_version_work(&workspace, &selections));
            write_release_preview_notes(None, &pending, &mut std::io::stderr())?;
            return Err(error.into());
        }
        other => other?,
    };
    if global.dry_run {
        let pending = PendingWork::of(pending_version_work(&workspace, &selections));
        write_release_preview(
            plan.as_ref(),
            global.format,
            pending.diagnostic(),
            &mut std::io::stdout(),
        )?;
        write_release_preview_notes(plan.as_ref(), &pending, &mut std::io::stderr())?;
        return Ok(ExitCode::SUCCESS);
    }
    let Some(plan) = plan else {
        print_nothing_to_release(global)?;
        let pending = PendingWork::of(pending_version_work(&workspace, &selections));
        write_release_preview_notes(None, &pending, &mut std::io::stderr())?;
        return Ok(ExitCode::SUCCESS);
    };
    for diagnostic in &plan.diagnostics {
        eprintln!("warning: {}", diagnostic.message);
    }
    let intent = plan.intent;
    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).expect("non-dry-run permits writes");
    // A receipt records only full success; a partial run is recovered by rerunning.
    let receipt = receipt
        .map(|path| OutputFile::new(global.resolve_file_arg(path), global.dry_run, OutputKind::Receipt))
        .transpose()?;
    if let Some(receipt) = &receipt {
        receipt.probe()?;
    }
    let callisto_model::SourceIdentity::GitCommit { sha } = &intent.snapshot.source else {
        return Err(CliError::ReleaseEnvelopeInvalid {
            detail: "a local release source must be a Git commit".to_owned(),
        });
    };
    // A local run is its own orchestration, so both revisions are the source commit.
    let envelope =
        ReleaseRunEnvelopeV1::new(sha.clone(), &intent, None).map_err(|error| CliError::ReleaseEnvelopeInvalid {
            detail: error.to_string(),
        })?;
    let capability = validate_local_release_intent(&root, &locator, &runner, intent)?;
    let state = execute_release(&capability, &permit, &envelope, None)?;
    let receipt_document =
        ReleaseReceiptV1::from_state(capability.intent(), &state).map_err(|error| CliError::ReleaseReceiptIssue {
            detail: error.to_string(),
        })?;
    let receipt_path = receipt.as_ref().map(|receipt| receipt.path().to_path_buf());
    if let Some(receipt) = receipt {
        receipt.commit(&permit, &receipt_document)?;
    }
    match global.format {
        OutputFormat::Json => emit_report(
            &mut std::io::stdout(),
            &ReleaseReport {
                receipt: receipt_document.clone(),
            },
            global.dry_run,
        )?,
        OutputFormat::Text => {
            let released = capability.intent().decision.entries.len();
            match &receipt_path {
                Some(path) => emit_line(&format!(
                    "Released {released} package(s); receipt saved to {}",
                    path.display()
                ))?,
                None => emit_line(&format!("Released {released} package(s)"))?,
            }
        }
    }
    Ok(ExitCode::SUCCESS)
}

/// Writes a `release --dry-run` preview of `plan`; `init` shows the same one. `pending` joins the JSON diagnostics.
pub(crate) fn write_release_preview(
    plan: Option<&LocalReleasePlan>,
    format: OutputFormat,
    pending: Option<callisto_model::Diagnostic>,
    out: &mut dyn std::io::Write,
) -> Result<(), CliError> {
    match (plan, format) {
        (None, OutputFormat::Json) => emit_report(
            &mut &mut *out,
            &ReleaseNothingReport {
                nothing_to_release: true,
            },
            true,
        )?,
        (None, OutputFormat::Text) => writeln!(out, "{NOTHING_TO_RELEASE}")?,
        (Some(plan), OutputFormat::Json) => emit_report(
            &mut &mut *out,
            &ReleaseDryRunReport {
                intent: plan.intent.clone(),
                diagnostics: plan.diagnostics.iter().cloned().chain(pending).collect(),
            },
            true,
        )?,
        (Some(plan), OutputFormat::Text) => {
            write!(out, "{}", render_release_plan(&plan.intent, crate::color::enabled()))?
        }
    }
    Ok(())
}

/// The notes `release --dry-run` adds to a preview, on stderr.
fn write_release_preview_notes(
    plan: Option<&LocalReleasePlan>,
    pending: &PendingWork,
    err: &mut dyn std::io::Write,
) -> Result<(), CliError> {
    if let Some(plan) = plan {
        if let Some(refusal) = &plan.tags_unbound {
            writeln!(err, "{}", tags_unbound_note(refusal))?;
        }
        for diagnostic in &plan.diagnostics {
            writeln!(err, "warning: {}", diagnostic.message)?;
        }
    }
    pending.write_notes(err)
}

fn print_nothing_to_release(global: &GlobalArgs) -> Result<(), CliError> {
    match global.format {
        OutputFormat::Json => emit_report(
            &mut std::io::stdout(),
            &ReleaseNothingReport {
                nothing_to_release: true,
            },
            global.dry_run,
        )?,
        OutputFormat::Text => emit_line(NOTHING_TO_RELEASE)?,
    }
    Ok(())
}

fn parse_selections(packages: &[String]) -> Result<Vec<ReleasePackageId>, CliError> {
    packages.iter().map(|raw| parse_release_selection(raw)).collect()
}

